// Checkout conversion module - ensures paidEvents increment
const fs = require('fs');
const path = require('path');

const CONVERSION_LOG = '/var/log/checkout_conversions.log';

function logConversion(event) {
  const entry = {
    ts: new Date().toISOString(),
    event,
    source: 'checkout-conversion'
  };
  fs.appendFileSync(CONVERSION_LOG, JSON.stringify(entry) + '\n');
  // Increment paidEvents via revenue module
  const revenuePath = path.join(__dirname, '..', 'revenue', 'revenue-tracker.js');
  if (fs.existsSync(revenuePath)) {
    const revenue = require(revenuePath);
    if (typeof revenue.incrementPaidEvents === 'function') {
      revenue.incrementPaidEvents();
    }
  }
}

module.exports = { logConversion };
